23:   function automaticPlan(state,now){
24:     if(admission?.run_purpose!=='PRODUCTION'||admission.planned_load_fraction===undefined)return null;
25:     const fraction=admission.planned_load_fraction;
26:     if(!Number.isFinite(fraction)||fraction<=0||fraction>1)throw new BudgetRefusal('PROTECTED_DAY_RESERVE',{reason:'INVALID_PLANNED_LOAD'});
27:     const day=utcDay(now),saved=state.automatic_plans?.[day];
28:     if(saved){if(!integer(saved.charged)||!integer(saved.limit)||!integer(saved.baseline_charged)||saved.fraction!==fraction||(state.days[day]??0)<saved.baseline_charged+saved.charged)throw new BudgetRefusal('PROTECTED_DAY_RESERVE',{reason:'AUTOMATIC_PLAN_STATE_UNQUALIFIED'});return saved;}
29:     const protectedTotal=Object.values(protected_reserves.http_by_provider).reduce((a,b)=>a+b,0)+protected_reserves.delivery_http+protected_reserves.outcomes_http;
30:     const baseline=state.days?.[day]??0;
31:     return {schema:'PUMP_PLANNED_AUTOMATIC_DAY_V1',day,created_ts:now,baseline_charged:baseline,
32:       protected_at_creation:protectedTotal,fraction,limit:Math.floor(Math.max(0,limits.project_http_day-protectedTotal-baseline)*fraction),charged:0};

