87:     if(mode==='AUTO'&&lane==='hot'&&run.lanes.hot+cost+limits.manual_http_run_reserve>limits.lanes.hot)throw new BudgetRefusal('RUN_MANUAL_RESERVE_PROTECTED');
88:     if(family==='LIQUIDATIONS'&&run.liquidations+cost>limits.liquidations_per_run)throw new BudgetRefusal('MAP_BUDGET_EXHAUSTED');
89:     if(candidate_id&&(run.candidates[candidate_id]??0)+cost>limits.deep_per_candidate)throw new BudgetRefusal('CANDIDATE_HTTP_EXHAUSTED');
90:     const protectedHttp=protected_reserves?.http_by_provider?.[provider];
91:     if(!integer(protectedHttp)||!integer(protected_reserves?.delivery_http)||!integer(protected_reserves?.outcomes_http))throw new BudgetRefusal('PROTECTED_RESERVES_NOT_MEASURED');
