93:     const deliveryProtection=family==='DELIVERY'||purpose==='DELIVERY'?0:protected_reserves.delivery_http;
94:     const outcomesProtection=mode==='STATISTICS'?0:protected_reserves.outcomes_http;
95:     const futureDiscovery=futureDiscoveryHttp(now,admission.discovery,{until_ts:utcBudgetPeriodEnd(now,'DAY')});
96:     const futureDiscoveryMonth=futureDiscoveryHttp(now,admission.discovery,{until_ts:utcBudgetPeriodEnd(now,'MONTH')});
97:     const futureCandidates=futureCandidateReserve(now,admission.future_candidates);
98:     const futureCandidatesMonth=futureCandidateReserve(now,admission.future_candidates,{period:'MONTH'});
