152:       const held=current?.outstanding?.[receipt.request_id];
153:       if(!held||held.run_id!==run_id)throw new BudgetRefusal('RESERVATION_NOT_OWNED');
154:       // Counts are monotonic: no HTTP attempt is refunded, including errors.
155:       if(state==='UNKNOWN')current.unknown[receipt.request_id]={...held,http_status};
156:       delete current.outstanding[receipt.request_id];
157:       const p=current.providers[receipt.provider];
158:       if(temporary_failure){p.consecutive_temporary_failures=Math.min(100,(p.consecutive_temporary_failures??0)+1);p.backoff_until=Math.max(p.backoff_until??0,clock()+temporaryDelay(p.consecutive_temporary_failures));}
159:       else if(successful_response)p.consecutive_temporary_failures=0;
160:       if(integer(retry_after_ms)&&retry_after_ms>0){const p=current.providers[receipt.provider];p.backoff_until=Math.max(p.backoff_until??0,clock()+retry_after_ms);}
161:       return {state:current,result:true};
162:     });
